'use strict';
// A computed `require(expr)` in a compiled package (#5389 Tier 2): a synchronous
// require, never a promise. It returns the target's module.exports as is (no
// `then` adoption) and throws MODULE_NOT_FOUND at the call for a missing one.
exports.load = function (name) {
  try {
    return require('./targets/' + name);
  } catch (e) {
    return 'caught ' + e.code;
  }
};
// An unrelated catch: what it receives is the error its own try throws.
exports.probe = function (o) {
  try {
    return o.k;
  } catch (e) {
    return 'probe ' + e.name;
  }
};
